const defaultRequest = {
  task_id: 'WF-BACKLOG-RECOMMEND-001',
  available_time: 'unknown',
  preferred_mode: 'any',
  max_options: 3,
  respect_wip: true,
};

const incoming = items && items[0] && items[0].json ? items[0].json : {};
const request = Object.keys(incoming).length ? { ...defaultRequest, ...incoming } : defaultRequest;

const wip = {
  IN_PROGRESS: [],
  VALIDATION: [],
  limits: {
    IN_PROGRESS: 2,
    VALIDATION: 3,
  },
};

const cards = [
  {
    backlog_id: 'EN-AGENT-001',
    title: 'Bootstrap plataforma multiagente local',
    current_status: 'READY',
    priority: 'P0',
    role: 'Solution / IoT Architect',
    reviewer_role: 'QA Engineer',
    effort: 'M',
    mode_fit: ['docs_governance', 'deep_work'],
    granularity: 'needs_task_breakdown',
    can_agent_execute: true,
    next_step: 'Continuar conectando Backlog Agent y luego Refinement Agent para operar el ciclo completo.',
    why_now: 'Es la base para que el resto del proyecto pueda avanzar con agentes, seleccion de trabajo, revision y evidencia.',
    dependencies: [],
    blockers: [],
  },
  {
    backlog_id: 'EN-QA-001',
    title: 'Implementar framework V&V y persistencia de evidencia',
    current_status: 'READY',
    priority: 'P0',
    role: 'QA Engineer',
    reviewer_role: 'Solution / IoT Architect',
    effort: 'M',
    mode_fit: ['docs_governance', 'deep_work'],
    granularity: 'needs_task_breakdown',
    can_agent_execute: true,
    next_step: 'Crear estructura de evidencia y reglas para que ninguna HU pase a DONE sin prueba verificable.',
    why_now: 'Acelera el proyecto sin perder control: cada avance de sensores, web o edge necesita evidencia trazable.',
    dependencies: [],
    blockers: [],
  },
  {
    backlog_id: 'EN-EDGE-001',
    title: 'Validar runtime Raspberry MQTT->DB',
    current_status: 'READY',
    priority: 'P0',
    role: 'DevOps / Platform Engineer',
    reviewer_role: 'QA Engineer',
    effort: 'M',
    mode_fit: ['coding', 'deep_work'],
    granularity: 'needs_task_breakdown',
    can_agent_execute: true,
    next_step: 'Definir ingesta minima MQTT a PostgreSQL/TimescaleDB con contratos V1.',
    why_now: 'Desbloquea la cadena real SENSOR -> TELEMETRY -> STORAGE y prepara la integracion web.',
    dependencies: [],
    blockers: [],
  },
  {
    backlog_id: 'HU-SOIL-001',
    title: 'Validar y caracterizar sensor de suelo 7-en-1',
    current_status: 'READY',
    priority: 'P0',
    role: 'QA Engineer',
    reviewer_role: 'Solution / IoT Architect',
    effort: 'M',
    mode_fit: ['physical_lab', 'docs_governance'],
    granularity: 'needs_task_breakdown',
    can_agent_execute: false,
    next_step: 'Refinar tareas T-SOIL pequenas sin reimplementar firmware existente.',
    why_now: 'Hay implementacion operacional existente y falta convertirla en evidencia validada.',
    dependencies: [],
    blockers: ['Requiere trabajo fisico/laboratorio para evidencia completa.'],
  },
  {
    backlog_id: 'HU-WATER-001',
    title: 'Implementar nodo de pH de agua',
    current_status: 'REFINEMENT',
    priority: 'P0',
    role: 'Firmware Engineer',
    reviewer_role: 'QA Engineer',
    effort: 'M',
    mode_fit: ['coding', 'physical_lab'],
    granularity: 'needs_refinement',
    can_agent_execute: true,
    next_step: 'Separar firmware, calibracion y validacion en HUs granulares.',
    why_now: 'Es P0, pero todavia necesita refinamiento antes de ejecucion segura.',
    dependencies: [],
    blockers: ['Necesita separar implementacion de calibracion/validacion.'],
  },
  {
    backlog_id: 'EN-PWR-001',
    title: 'Diseñar arquitectura de potencia y protecciones',
    current_status: 'REFINEMENT',
    priority: 'P0',
    role: 'Hardware Engineer',
    reviewer_role: 'QA Engineer',
    effort: 'M',
    mode_fit: ['physical_lab', 'deep_work'],
    granularity: 'needs_refinement',
    can_agent_execute: false,
    next_step: 'Dividir calculos, protecciones, gabinete, pruebas y procurement.',
    why_now: 'Control fisico, valvulas y bombas dependen de potencia/protecciones confiables.',
    dependencies: [],
    blockers: ['Requiere decisiones de hardware y aprobacion humana para compras/control fisico.'],
  },
];

const priorityWeight = { P0: 0, P1: 1, P2: 2 };
const statusWeight = { READY: 0, REFINEMENT: 1, BACKLOG: 2, IDEA: 3, IN_PROGRESS: 4, VALIDATION: 5, DONE: 99 };
const effortWeight = { XS: 0, S: 1, M: 2, L: 3 };

function modeScore(card) {
  if (!request.preferred_mode || request.preferred_mode === 'any') return 0;
  return card.mode_fit.includes(request.preferred_mode) ? -2 : 2;
}

function timeScore(card) {
  if (request.available_time === 'short') return effortWeight[card.effort] || 2;
  if (request.available_time === 'medium') return card.effort === 'M' ? -1 : 0;
  if (request.available_time === 'long') return card.effort === 'M' || card.effort === 'L' ? -1 : 0;
  return 0;
}

const canTakeMore = !request.respect_wip || wip.IN_PROGRESS.length < wip.limits.IN_PROGRESS;
const candidates = cards
  .filter((card) => card.current_status !== 'DONE')
  .filter((card) => canTakeMore || card.current_status === 'IN_PROGRESS')
  .map((card) => ({
    ...card,
    score: (priorityWeight[card.priority] ?? 9) * 10
      + (statusWeight[card.current_status] ?? 9) * 3
      + modeScore(card)
      + timeScore(card),
  }))
  .sort((a, b) => a.score - b.score || a.backlog_id.localeCompare(b.backlog_id))
  .slice(0, request.max_options || 3)
  .map(({ score, ...card }) => ({
    ...card,
    work_type: card.can_agent_execute ? 'agent_or_mixed' : 'human_or_mixed',
    recommendation_warning: card.granularity === 'needs_task_breakdown' || card.granularity === 'needs_refinement'
      ? 'Antes de ejecutar, refinar en HUs/tareas mas pequenas con evidencia esperada.'
      : 'Lista para ejecucion acotada.',
  }));

return [{
  json: {
    task_id: request.task_id,
    agent_id: 'AGENT-BKL-001',
    status: 'SUCCESS',
    summary: 'Recomendacion de siguiente trabajo generada desde snapshot del tablero Kanban versionado.',
    wip_status: {
      in_progress_count: wip.IN_PROGRESS.length,
      in_progress_limit: wip.limits.IN_PROGRESS,
      can_take_more: canTakeMore,
    },
    selection_context: {
      available_time: request.available_time,
      preferred_mode: request.preferred_mode,
      max_options: request.max_options,
    },
    recommended_options: candidates,
    requires_human_selection: true,
    question_for_human: 'Cual opcion quieres tomar ahora?',
    next_action_after_selection: 'Enviar la opcion elegida a WF-REFINE-STORY-001 antes de ejecutar.',
    evidence: [
      'project/kanban/board.yaml',
      'project/backlog/master-backlog.yaml',
      'project/agents-operating-model.md',
      'project/roles/expert-role-catalog.yaml'
    ],
  }
}];
